import {expect,test} from "bun:test";
import {readFileSync} from "node:fs";
import {resolve} from "node:path";
import {Database} from "bun:sqlite";
import {inspectNeutralBindingOwnership,type BindingFixture} from "__HELPER__";
__IMPORTS__
const root=resolve(import.meta.dir,"__ROOT__"),fixturePath="__FIXTURE__",read=(path:string)=>readFileSync(resolve(root,path),"utf8");
const project=(row:BindingFixture["cases"][number]):[number,unknown][]=>{__PROJECTION__};
test("canonical __PROFILE__ binding is owned beside the types with direct Record authority",async()=>{const result=await inspectNeutralBindingOwnership(root,fixturePath);expect(result.types).toBe(__COUNT__);});
test("closed __PROFILE__ binding fields match first-party admission and independent JSON/SQLite",()=>{const fixture=JSON.parse(read(fixturePath))as BindingFixture,sql=new Database(":memory:");try{sql.run("CREATE TABLE fields(id INTEGER PRIMARY KEY,value TEXT NOT NULL)");for(const row of fixture.cases){const actual=project(row);expect(actual).toEqual(row.expectedFields);sql.run("DELETE FROM fields");for(const [id,value]of actual)sql.run("INSERT INTO fields VALUES(?,?)",[id,JSON.stringify(value)]);const queried=sql.query("SELECT id,value FROM fields ORDER BY id").all()as{id:number;value:string}[];expect(queried.map(row=>[row.id,JSON.parse(row.value)])).toEqual(row.expectedFields);console.log("[DEBUG] canonical __PROFILE__ binding field oracle",row.id);}}finally{sql.close();}});
test("bounded __PROFILE__ binding witnesses admit private edits and refuse owner/dependency substitution",async()=>{const fixture=JSON.parse(read(fixturePath))as BindingFixture;for(const item of fixture.sourceCases){const source=read(fixture.binding),mutated=item.id==="formatting"?source.replaceAll("impl DslField","impl  DslField"):item.id==="private-extension"?source+"\nfn private_owner_extension()->usize{1}\n":item.id==="missing-type-owner"?source.replace("impl DslField for "+fixture.types[0],"impl DslField for WrongOwner"):source;const reader=(path:string)=>path===fixture.binding?mutated:path===fixture.manifest&&item.id==="hostile-dependency"?read(path).replace('[dependencies]','[dependencies]\nsemio-framework-os-kernel = { path = "../../../🛍️products/💻️os/📦️packages/🦀️rust" }'):read(path);if(item.accepted)expect((await inspectNeutralBindingOwnership(root,fixturePath,reader)).types).toBe(fixture.types.length);else await expect(inspectNeutralBindingOwnership(root,fixturePath,reader)).rejects.toThrow();}});
